(()=>{if((window.scc??(window.scc={})).enseignesSimilaires)return;window.scc.enseignesSimilaires=!0;const r=()=>{const e=document.querySelector(".brand-related-section");if(!e)return;const s=location.pathname.replace(/\/+$/,"");let i=0;for(const o of[...e.querySelector(".brands-grid")?.children??[]]){const t=o.querySelector(".brands-card"),c=t?.querySelector("[data-slug]")?.textContent.trim()??"",n=c?`/enseignes/${c}`:"";if(t&&n&&t.setAttribute("href",n),n===s){o.remove();continue}i+=1}i||e.remove()};document.readyState==="loading"?document.addEventListener("DOMContentLoaded",r,{once:!0}):r()})();
